        "Arn": "arn:aws:iam::yourAccountID:role/yourIAMRoleName"
    }
} Note: Replace yourAccessKeyId , yourSecretAccessKey , yourSessionToken , yourAssumedRoleId , yourAccountID , and yourIAMRoleName with your values.

