		"Sid": "AllowCrossAccountAccess",
		"Effect": "Allow",
		"Principal": {
			"AWS": [
				"arn:aws:iam::AccountA-ID:user/user1",
				"arn:aws:iam::AccountA-ID:role/role01"
			]
		},
		"Action": [
			"s3:GetObject",
