// TODO implement
callback(null, "This message header was processed by Amazon " +event.headers["header1"]);
}; 9. Choose Save . For more information, see Building Lambda functions with Node.js . Create an API Gateway REST API 1. Open the API Gateway console . 2. Choose Create API . -or- (If this is your first time using API Gateway) A page that introduces you to the features of the service appears. Under REST API , choose Build . When the Create Example API popup appears, choose OK . 3. For Choose an API type , in the REST API pane, choose Build . 4. Under Create new API , choose New API . 5. Under Settings , do the following: For API name , enter a name that describes your API's purpose. For example: SendtoLambda .

choices:
A)
```
exports.handler = (event, context, callback) => {
  const header1 = event.headers["header1"];
  const processedHeader = header1.split("").reverse().join("");
  callback(null, "This message header was processed by Amazon " + processedHeader);
};
```

B)
```
exports.handler = (event, context, callback) => {
  const header1 = event.headers["header1"];
  const processedHeader = header1.toUpperCase();
  callback(null, "This message header was processed by Amazon " + processedHeader);
};
```

C)
```
exports.handler = (event, context, callback) => {
  const header1 = event.headers["header1"];
  const processedHeader = header1.split(" ").join("_");
  callback(null, "This message header was processed by Amazon " + processedHeader);
};
```

D)
```
exports.handler = (event, context, callback) => {
  const header1 = event.headers["header1"];
  const processedHeader = header1.replace(/[A-Z]/g, function(match) {
    return match.toLowerCase();
  });
  callback(null, "This message header was processed by Amazon " + processedHeader);
};
```

correct_answer:
D)
```
exports.handler = (event, context, callback) => {
  const header1 = event.headers["header1"];
  const processedHeader = header1.replace(/[A-Z]/g, function(match) {
    return match.toLowerCase();
  });
  callback(null, "This message header was processed by Amazon " + processedHeader);
};
```

